// Actual full-FLOAT stores, byte admission and allocation rollback. The renamed
// private class cannot interpose on SurfaceRenderer's own compiled target.
#define main established_material_fixture
#include "mtoon-render.cpp"
#undef main
#define LinearSceneTarget FixtureLinearSceneTarget
#include "../src/render-target.hpp"
#undef LinearSceneTarget
#include <EGL/egl.h>
namespace {
bool fail_color=false,fail_depth=false;size_t color_allocations=0,depth_allocations=0;
GLuint color_name(){GLint type=0,name=0;glGetFramebufferAttachmentParameteriv(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE,&type);check(type==GL_TEXTURE,"Private linear scene owns an actual color texture");glGetFramebufferAttachmentParameteriv(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME,&name);return GLuint(name);}
void full_format(){auto name=color_name();glBindTexture(GL_TEXTURE_2D,name);GLint format=0,bits=0;glGetTexLevelParameteriv(GL_TEXTURE_2D,0,GL_TEXTURE_INTERNAL_FORMAT,&format);check(format==GL_RGBA32F,"Actual scene color internal format is genuine RGBA32F without HALF fallback");for(auto component:{GL_TEXTURE_RED_SIZE,GL_TEXTURE_GREEN_SIZE,GL_TEXTURE_BLUE_SIZE,GL_TEXTURE_ALPHA_SIZE}){glGetTexLevelParameteriv(GL_TEXTURE_2D,0,component,&bits);check(bits==32,"Actual scene color component retains full FLOAT precision");}}
struct OwnedTarget:FixtureLinearSceneTarget{using FixtureLinearSceneTarget::FixtureLinearSceneTarget;~OwnedTarget(){clear(true);}};
struct DepthStencilDestination{GLuint f=0,c=0,d=0;DepthStencilDestination(){glGenFramebuffers(1,&f);glBindFramebuffer(GL_FRAMEBUFFER,f);glGenTextures(1,&c);glBindTexture(GL_TEXTURE_2D,c);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,96,96,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,c,0);glGenRenderbuffers(1,&d);glBindRenderbuffer(GL_RENDERBUFFER,d);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH32F_STENCIL8,96,96);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_STENCIL_ATTACHMENT,GL_RENDERBUFFER,d);check(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE,"Actual FLOAT-depth/stencil destination is complete");}~DepthStencilDestination(){glDeleteRenderbuffers(1,&d);glDeleteTextures(1,&c);glDeleteFramebuffers(1,&f);}};
void pool_and_failure(){
 Fbo destination;OwnedTarget target;destination.bind();target.begin(16,16,SurfaceOutputEncoding::Linear);full_format();const auto a=color_name();target.abort();check(target.bytes()==16*16*20,"RGBA32F plus conservative depth slot charges20 bytes per pixel");
 destination.bind();target.begin(24,16,SurfaceOutputEncoding::Linear);const auto b=color_name();glClearColor(.125f,.25f,.5f,.75f);glClear(GL_COLOR_BUFFER_BIT);target.abort();check(target.bytes()==(16*16+24*16)*20,"Two actual cached views charge their combined FLOAT stores");
 for(bool depth:{false,true}){
  destination.bind();const auto prior=color_allocations;fail_color=!depth;fail_depth=depth;check(rejects([&]{target.begin(20,20,SurfaceOutputEncoding::Linear);}),"Real failed color/depth allocation rejects the replacement scene target");check(!fail_color&&!fail_depth,"Requested genuine GL allocation fault was reached");check(!target.pending()&&glGetError()==GL_NO_ERROR,"Failed target probes clean their GL errors and pending state");GLint bound=0;glGetIntegerv(GL_DRAW_FRAMEBUFFER_BINDING,&bound);check(GLuint(bound)==destination.f,"Failed scene allocation restores the original caller framebuffer");check(glIsTexture(b),"Accepted target survives failed replacement allocation");check(target.bytes()==24*16*20,"Failed replacement retains exactly the accepted target charge");
  destination.bind();target.begin(24,16,SurfaceOutputEncoding::Linear);check(color_name()==b&&color_allocations==prior+1,"Accepted view reuses its exact old target without another allocation after failure");std::array<float,4> pixel{};glReadPixels(0,0,1,1,GL_RGBA,GL_FLOAT,pixel.data());check(pixel==std::array<float,4>{.125f,.25f,.5f,.75f},"Accepted FLOAT pixels survive genuine failed allocation exactly");target.abort();
 }
 check(!glIsTexture(a),"Older cached view may retire while preserving accepted front on replacement failure");destination.bind();target.begin(32,16,SurfaceOutputEncoding::Linear);const auto c=color_name();target.abort();destination.bind();target.begin(40,16,SurfaceOutputEncoding::Linear);target.abort();check(!glIsTexture(b)&&glIsTexture(c)&&target.bytes()==(32*16+40*16)*20,"LRU pooling retains at most two actual views with exact FLOAT charges");target.clear(true);check(target.bytes()==0&&!target.pending()&&!glIsTexture(c),"Explicit target invalidation releases all requested scene stores");
}
void admission(){
 Fbo destination;OwnedTarget bounded((16*16+24*16)*20);destination.bind();bounded.begin(16,16,SurfaceOutputEncoding::Linear);bounded.abort();destination.bind();bounded.begin(24,16,SurfaceOutputEncoding::Linear);const auto accepted=color_name();bounded.abort();auto prior=color_allocations;destination.bind();check(rejects([&]{bounded.begin(32,16,SurfaceOutputEncoding::Linear);})&&color_allocations==prior,"Byte admission includes candidate plus accepted target and refuses before GL allocation");check(glIsTexture(accepted)&&bounded.bytes()==24*16*20,"Byte refusal retains the exact accepted front and its accurate charge");destination.bind();bounded.begin(24,16,SurfaceOutputEncoding::Linear);check(color_name()==accepted&&color_allocations==prior,"Byte-refused view leaves accepted dimensions reusable without allocation");bounded.abort();destination.bind();check(rejects([&]{bounded.begin(8192,8192,SurfaceOutputEncoding::Linear);})&&color_allocations==prior,"Original16MiPixel per-view bound still rejects before allocating");
 DepthStencilDestination stencil;OwnedTarget deep;deep.begin(16,16,SurfaceOutputEncoding::Linear);full_format();check(deep.bytes()==16*16*24,"RGBA32F plus actual FLOAT depth/stencil charges24 bytes per pixel");deep.abort();destination.bind();deep.begin(16,16,SurfaceOutputEncoding::Linear);check(deep.bytes()==16*16*(24+20),"Same-size destination depth-format transition owns separately charged stores");deep.abort();
}
void production_format(){Fbo destination;SurfaceRenderer renderer;renderer.set_deferred_resolve(true);destination.bind();renderer.draw(snapshot(),{},identity,{0,0,2},96,96,true);full_format();renderer.resolve();check(glGetError()==GL_NO_ERROR,"Actual production deferred FLOAT target resolves with valid state");}
}
extern "C" {
void __real_glTexImage2D(GLenum,GLint,GLint,GLsizei,GLsizei,GLint,GLenum,GLenum,const void*);
void __wrap_glTexImage2D(GLenum a,GLint b,GLint c,GLsizei d,GLsizei e,GLint f,GLenum g,GLenum h,const void*i){if(c==GL_RGBA32F){++color_allocations;if(fail_color){fail_color=false;__real_glTexImage2D(a,b,c,-1,e,f,g,h,i);return;}}__real_glTexImage2D(a,b,c,d,e,f,g,h,i);}
void __real_glRenderbufferStorage(GLenum,GLenum,GLsizei,GLsizei);
void __wrap_glRenderbufferStorage(GLenum a,GLenum b,GLsizei c,GLsizei d){++depth_allocations;if(fail_depth){fail_depth=false;__real_glRenderbufferStorage(a,b,-1,d);return;}__real_glRenderbufferStorage(a,b,c,d);}
}
int main(int argc,char**argv)try{NativeGraphics graphics;const auto device=std::string(reinterpret_cast<const char*>(glGetString(GL_RENDERER)));std::cout<<"ACTUAL_RENDERER "<<device<<'\n';if(argc>1&&std::string_view(argv[1])=="--hardware")check(device.find("Arc")!=std::string::npos&&device.find("A770")!=std::string::npos,"Target stores execute on requested actual Arc");pool_and_failure();admission();production_format();check(glGetError()==GL_NO_ERROR,"Target allocation/admission/format controls leave the real GL error queue clean");std::cout<<"PASS "<<checks<<" actual FLOAT scene target controls\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
